import { useAuth } from "@/_core/hooks/useAuth";
import { startLogin } from "@/const";
import { useTheme } from "@/contexts/ThemeContext";
import { exportFinancialPdf, exportFinancialWorkbook } from "@/lib/financialExports";
import { trpc } from "@/lib/trpc";
import {
  exportJson,
  createLocalTransaction,
  filterLocalTransactions,
  loadLocalTransactions,
  parseBackupJson,
  saveLocalTransactions,
  type LocalTransaction,
  type PaymentMethod,
} from "@/lib/localTransactions";
import { appendInvestmentOperation, applyInvestmentQuote, consolidateInvestmentOperations, createLocalInvestment, investmentCategories, investmentCost, investmentMarketValue, investmentProfitability, investmentValue, loadLocalInvestments, saveLocalInvestments, type InvestmentCategory, type LocalInvestment, type InvestmentOperationType } from "@/lib/localInvestments";
import { applyCreditPurchase, createLocalCreditCard, deleteLocalCreditCard, loadLocalCreditCards, removeCreditPurchase, saveLocalCreditCards, setCreditCardInvoicePaid, updateLocalCreditCard, type CreditCard } from "@/lib/localCreditCards";
import { dashboardWidgetKeys, type DashboardWidgetKey } from "@/lib/dashboardPreferences";
import CreditCardsPage, { NextInvoiceCard, type CreditCardForm } from "@/pages/CreditCardsPage";
import { Button } from "@/components/ui/button";
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from "@/components/ui/alert-dialog";
import { recordAuthEvent } from "@/lib/authEvents";
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuTrigger } from "@/components/ui/dropdown-menu";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Tooltip as UiTooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip";
import { toast } from "sonner";
import { ArrowDown, ArrowDownRight, ArrowUp, ArrowUpRight, BarChart3, BriefcaseBusiness, CalendarDays, ChevronDown, CircleArrowDown, CircleArrowUp, Coins, Download, FileSpreadsheet, FileText, Landmark, LayoutDashboard, Loader2, LogOut, Menu, Moon, PanelLeftClose, PanelLeftOpen, Pencil, Plus, ReceiptText, Settings2, Sparkles, Sun, Trash2, Wallet, X, CreditCard as CreditCardIcon } from "lucide-react";
import { useEffect, useMemo, useRef, useState } from "react";
import { Link, useLocation } from "wouter";
import { Area, AreaChart, Bar, BarChart, CartesianGrid, Cell, Legend, Pie, PieChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from "recharts";

type FormState = { id?: number; type: "income" | "expense"; description: string; amount: string; category: string; occurredAt: string; icon?: string; paymentMethod?: PaymentMethod; creditCardId?: number; installmentsTotal?: number; buyer?: string };
type InvestmentFormState = { id?: number; ticker: string; category: InvestmentCategory; institution: string; quantity: string; averagePrice: string; currentValue: string; operationType: InvestmentOperationType; operationDate: string; notes: string };
type DeleteRequest = { kind: "transaction" | "investment" | "creditCard"; id: number };
const monthNames = ["Jan", "Fev", "Mar", "Abr", "Mai", "Jun", "Jul", "Ago", "Set", "Out", "Nov", "Dez"];
const defaultYears = Array.from({ length: 11 }, (_, index) => new Date().getFullYear() - index);
const money = new Intl.NumberFormat("pt-BR", { style: "currency", currency: "BRL" });
const usdMoney = new Intl.NumberFormat("en-US", { style: "currency", currency: "USD" });
const chartColors = ["#c084fc", "#22d3ee", "#34d399", "#fbbf24", "#fb7185", "#60a5fa", "#a78bfa"];
function formatInvestmentMoney(item: Pick<LocalInvestment, "category">, value: number) { return item.category === "dollar" ? usdMoney.format(value) : money.format(value); }


function initialForm(type: "income" | "expense" = "income"): FormState { return { type, description: "", amount: "", category: "", occurredAt: new Date().toISOString().slice(0, 10), icon: type === "income" ? "↗" : "◒", paymentMethod: type === "expense" ? "cash" : undefined, installmentsTotal: 1 }; }
function initialInvestmentForm(): InvestmentFormState { return { ticker: "", category: "fixed-income", institution: "", quantity: "", averagePrice: "", currentValue: "", operationType: "buy", operationDate: new Date().toISOString().slice(0, 10), notes: "" }; }

export default function Home() {
  const { user, loading, logout } = useAuth();
  const { theme, toggleTheme } = useTheme();
  const [sidebarCollapsed, setSidebarCollapsed] = useState(() => localStorage.getItem("findash-lvo:sidebar-collapsed") === "true");
  const [location, setLocation] = useLocation();
  const now = new Date();
  const [month, setMonth] = useState(now.getMonth() + 1);
  const [year, setYear] = useState(now.getFullYear());
  const [form, setForm] = useState<FormState | null>(null);
  const [selectedDate, setSelectedDate] = useState(() => new Date().toISOString().slice(0, 10));
  const [performanceRange, setPerformanceRange] = useState<"week" | "month" | "year">("year");
  const [investmentForm, setInvestmentForm] = useState<InvestmentFormState | null>(null);
  const [investments, setInvestments] = useState<LocalInvestment[]>([]);
  const [hydratedInvestmentsId, setHydratedInvestmentsId] = useState<number | string | null>(null);
  const [creditCards, setCreditCards] = useState<CreditCard[]>([]);
  const [hydratedCreditCardsId, setHydratedCreditCardsId] = useState<number | string | null>(null);
  const [deleteRequest, setDeleteRequest] = useState<DeleteRequest | null>(null);
  const quoteItems = useMemo(() => investments.filter(item => item.ticker.trim()).map(item => ({ ticker: item.ticker.trim().toUpperCase(), category: item.category })), [investments]);
  const quoteQuery = trpc.quotes.brapiBatch.useQuery({ items: quoteItems }, { enabled: Boolean(user) && quoteItems.length > 0, staleTime: 5 * 60 * 1000, refetchOnWindowFocus: false });
  const marketWidgetQuery = trpc.quotes.brapiBatch.useQuery({ items: [{ ticker: "USD-BRL", category: "dollar" }, { ticker: "BTC", category: "crypto" }] }, { enabled: Boolean(user), staleTime: 5 * 60 * 1000, refetchOnWindowFocus: false });
  const defaultHistoryTicker = investments.find(item => item.ticker.trim())?.ticker.trim().toUpperCase() ?? "";
  const [historyTicker, setHistoryTicker] = useState("");
  useEffect(() => {
    if (!historyTicker || !investments.some(item => item.ticker.trim().toUpperCase() === historyTicker)) setHistoryTicker(defaultHistoryTicker);
  }, [defaultHistoryTicker, historyTicker, investments]);
  const [historyRange, setHistoryRange] = useState<"1mo" | "6mo" | "1y">("1mo");
  const historyQuery = trpc.quotes.historical.useQuery({ symbol: historyTicker, range: historyRange }, { enabled: Boolean(user && historyTicker), staleTime: 15 * 60 * 1000, refetchOnWindowFocus: false });
  const isTransactions = location === "/lancamentos";
  const isInvestments = location === "/investimentos";
  const isCreditCards = location === "/cartoes";
  const [transactions, setTransactions] = useState<LocalTransaction[]>([]);
  const [logoutOpen, setLogoutOpen] = useState(false);
  const [paymentFilter, setPaymentFilter] = useState<PaymentMethod | "all">("all");
  const [hydratedStorageId, setHydratedStorageId] = useState<number | string | null>(null);
  const importInputRef = useRef<HTMLInputElement>(null);
  const userStorageId = user?.id ?? "default";

  useEffect(() => {
    if (user) {
      setInvestments(loadLocalInvestments(userStorageId));
      setHydratedInvestmentsId(userStorageId);
    }
  }, [user, userStorageId]);

  useEffect(() => {
    if (user && hydratedInvestmentsId === userStorageId) saveLocalInvestments(userStorageId, investments);
  }, [investments, user, userStorageId, hydratedInvestmentsId]);

  useEffect(() => {
    if (user) {
      setCreditCards(loadLocalCreditCards(userStorageId));
      setHydratedCreditCardsId(userStorageId);
    }
  }, [user, userStorageId]);

  useEffect(() => {
    if (user && hydratedCreditCardsId === userStorageId) saveLocalCreditCards(userStorageId, creditCards);
  }, [creditCards, user, userStorageId, hydratedCreditCardsId]);

  useEffect(() => {
    if (!quoteQuery.data?.length) return;
    setInvestments(current => {
      let changed = false;
      const next = current.map(item => {
        const quote = quoteQuery.data.find(result => result.ticker.toUpperCase() === item.ticker.trim().toUpperCase());
        if (!quote) return item;
        const nextItem = applyInvestmentQuote(item, quote);
        if (nextItem.marketPrice === item.marketPrice && nextItem.currentValue === item.currentValue && nextItem.quoteChangePercent === item.quoteChangePercent && nextItem.quoteFetchedAt === item.quoteFetchedAt && nextItem.quoteSource === item.quoteSource && nextItem.quoteError === item.quoteError) return item;
        changed = true;
        return nextItem;
      });
      return changed ? next : current;
    });
  }, [quoteQuery.data]);

  useEffect(() => {
    setSelectedDate(`${year}-${String(month).padStart(2, "0")}-01`);
  }, [month, year]);

  useEffect(() => {
    if (user) {
      setTransactions(loadLocalTransactions(userStorageId));
      setHydratedStorageId(userStorageId);
    }
  }, [user, userStorageId]);

  useEffect(() => {
    if (user && hydratedStorageId === userStorageId) saveLocalTransactions(userStorageId, transactions);
  }, [transactions, user, userStorageId, hydratedStorageId]);

  const saving = false;
  const refreshQuotes = async () => {
    try {
      const result = await quoteQuery.refetch();
      const failures = (result.data ?? []).filter(item => !item.ok);
      if (failures.length) toast.error(`Não foi possível atualizar ${failures.length} cotação(ões)`);
      else toast.success("Cotações atualizadas com sucesso");
    } catch (error) {
      toast.error(error instanceof Error ? error.message : "Não foi possível atualizar as cotações");
    }
  };
  useEffect(() => { localStorage.setItem("findash-lvo:sidebar-collapsed", String(sidebarCollapsed)); }, [sidebarCollapsed]);
  const visibleTransactions = useMemo(() => {
    const periodTransactions = filterLocalTransactions(transactions, month, year);
    return paymentFilter === "all" ? periodTransactions : periodTransactions.filter(item => item.paymentMethod === paymentFilter);
  }, [transactions, month, year, paymentFilter]);
  const summary = useMemo(() => visibleTransactions.reduce((acc, item) => { const value = Number(item.amount); item.type === "income" ? acc.income += value : acc.expense += value; return acc; }, { income: 0, expense: 0 }), [visibleTransactions]);
  const yearOptions = useMemo(() => Array.from(new Set([...defaultYears, ...transactions.map(item => new Date(item.occurredAt).getFullYear())])).sort((a, b) => b - a), [transactions]);
  const chartData = useMemo(() => { const buckets = new Map<number, { month: string; income: number; expense: number }>(); for (const item of visibleTransactions) { const m = new Date(item.occurredAt).getMonth(); const current = buckets.get(m) ?? { month: monthNames[m], income: 0, expense: 0 }; current[item.type] += Number(item.amount); buckets.set(m, current); } return Array.from(buckets.values()).sort((a, b) => monthNames.indexOf(a.month) - monthNames.indexOf(b.month)); }, [visibleTransactions]);

  if (loading) return <div className="min-h-screen grid place-items-center"><div className="animate-pulse text-muted-foreground">Carregando seu espaço financeiro...</div></div>;
  if (!user) return <Landing onLogin={startLogin} />;

  const submit = (event: React.FormEvent) => {
    event.preventDefault();
    if (!form || !user) return;
    const amount = Number(form.amount);
    if (!form.description.trim() || !form.category.trim() || !Number.isFinite(amount) || amount <= 0) {
      toast.error("Preencha descrição, valor e categoria");
      return;
    }
    const paymentMethod = form.type === "expense" ? (form.paymentMethod ?? "cash") : undefined;
    const installmentsTotal = paymentMethod === "credit" ? Math.max(1, Math.floor(Number(form.installmentsTotal || 1))) : undefined;
    const selectedCard = form.creditCardId ? creditCards.find(card => card.id === form.creditCardId) : undefined;
    if (paymentMethod === "credit" && (!selectedCard || (selectedCard.cardType === "shared" && !form.buyer?.trim()))) {
      toast.error(selectedCard?.cardType === "shared" ? "Informe quem realizou a compra" : "Escolha um cartão para a compra no crédito");
      return;
    }
    const previousTransaction = form.id ? transactions.find(item => item.id === form.id) : undefined;
    const purchaseId = previousTransaction?.purchaseId ?? Date.now();
    const nowIso = new Date().toISOString();
    if (form.id) {
      setTransactions(current => current.map(item => item.id === form.id ? {
        ...item,
        type: form.type,
        description: form.description.trim(),
        amount: amount.toFixed(2),
        category: form.category.trim(),
        icon: form.icon,
        occurredAt: new Date(`${form.occurredAt}T12:00:00`).toISOString(),
        paymentMethod,
        creditCardId: form.creditCardId,
        installmentsTotal,
        updatedAt: nowIso,
      } : item));
      if (previousTransaction?.paymentMethod === "credit" && previousTransaction.purchaseId) {
        setCreditCards(current => removeCreditPurchase(current, previousTransaction.purchaseId!));
      }
      if (paymentMethod === "credit" && form.creditCardId) {
        setCreditCards(current => applyCreditPurchase(current, { cardId: form.creditCardId!, purchaseId, description: form.description.trim(), buyer: form.buyer, total: amount, purchasedAt: form.occurredAt, installments: installmentsTotal || 1 }));
      }
      toast.success("Lançamento atualizado");
    } else {
      setTransactions(current => createLocalTransaction(current, {
        userId: Number(user.id),
        type: form.type,
        description: form.description.trim(),
        amount: paymentMethod === "credit" ? (amount / (installmentsTotal || 1)).toFixed(2) : amount.toFixed(2),
        category: form.category.trim(),
        icon: form.icon,
        occurredAt: new Date(`${form.occurredAt}T12:00:00`).toISOString(),
        paymentMethod,
        creditCardId: form.creditCardId,
        creditTotal: paymentMethod === "credit" ? amount.toFixed(2) : undefined,
        installmentIndex: paymentMethod === "credit" ? 1 : undefined,
        installmentsTotal,
        purchaseId: paymentMethod === "credit" ? purchaseId : undefined,
      }));
      if (paymentMethod === "credit" && form.creditCardId) {
        setCreditCards(current => applyCreditPurchase(current, { cardId: form.creditCardId!, purchaseId, description: form.description.trim(), buyer: form.buyer, total: amount, purchasedAt: form.occurredAt, installments: installmentsTotal || 1 }));
      }
      toast.success(paymentMethod === "credit" ? "Compra parcelada adicionada à fatura" : "Lançamento adicionado");
    }
    setForm(null);
  };
  const remove = (id: number) => {
    const removed = transactions.find(item => item.id === id);
    setTransactions(current => current.filter(item => item.id !== id));
    if (removed?.paymentMethod === "credit" && removed.purchaseId) setCreditCards(current => removeCreditPurchase(current, removed.purchaseId!));
    toast.success("Lançamento excluído");
  };
  const confirmDelete = () => {
    if (!deleteRequest) return;
    if (deleteRequest.kind === "transaction") remove(deleteRequest.id);
    if (deleteRequest.kind === "investment") setInvestments(current => current.filter(item => item.id !== deleteRequest.id));
    if (deleteRequest.kind === "creditCard") setCreditCards(current => deleteLocalCreditCard(current, deleteRequest.id));
    if (deleteRequest.kind !== "transaction") toast.success(deleteRequest.kind === "investment" ? "Investimento excluído" : "Cartão excluído");
    setDeleteRequest(null);
  };
  const downloadBackup = () => {
    const blob = new Blob([exportJson(transactions)], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const anchor = document.createElement("a");
    anchor.href = url;
    anchor.download = `findash-lvo-backup-${new Date().toISOString().slice(0, 10)}.json`;
    anchor.click();
    URL.revokeObjectURL(url);
    toast.success("Backup exportado");
  };
  const importBackup = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    event.target.value = "";
    if (!file) return;
    try {
      const imported = parseBackupJson(await file.text());
      setTransactions(imported.map((item, index) => ({ ...item, id: index + 1, userId: Number(user?.id ?? 1) })));
      toast.success(`${imported.length} lançamento(s) importado(s)`);
    } catch (error) {
      toast.error(error instanceof Error ? error.message : "Não foi possível importar o backup");
    }
  };
  const exportExcel = () => {
    exportFinancialWorkbook({ transactions, investments, creditCards, income: summary.income, expense: summary.expense });
    toast.success("Planilha Excel exportada");
  };
  const exportPdf = () => {
    const performance = buildPerformanceData(transactions, year, month, performanceRange, selectedDate);
    exportFinancialPdf({ transactions, investments, creditCards, income: summary.income, expense: summary.expense, performance });
    toast.success("Relatório PDF exportado");
  };
  const grouped = { income: visibleTransactions.filter(t => t.type === "income"), expense: visibleTransactions.filter(t => t.type === "expense") };
  const saveCreditCard = (form: CreditCardForm) => {
    const nowIso = new Date().toISOString();
    if (form.id) { const { id: _id, ...cardPatch } = form; setCreditCards(current => updateLocalCreditCard(current, form.id!, cardPatch, new Date(nowIso))); }
    else setCreditCards(current => createLocalCreditCard(current, { ...form, userId: Number(user.id) }));
  };
  const confirmLogout = async () => {
    recordAuthEvent("logout_requested");
    try {
      await logout();
      recordAuthEvent("logout_succeeded");
      toast.success("Sessão encerrada");
    } catch (error) {
      recordAuthEvent("logout_failed", { message: error instanceof Error ? error.message : "unknown" });
      toast.error("Não foi possível encerrar a sessão");
    } finally {
      setLogoutOpen(false);
    }
  };
  const toggleCreditCardPaid = (id: number, invoiceMonth = new Date().toISOString().slice(0, 7)) => setCreditCards(current => {
    const card = current.find(item => item.id === id);
    if (!card) return current;
    const currentPaid = card.paidInvoices?.[invoiceMonth] ?? (invoiceMonth === card.invoiceMonth ? card.isPaid : false);
    return setCreditCardInvoicePaid(current, id, invoiceMonth, !currentPaid);
  });

  return <div className="app-shell min-h-screen text-foreground">
    <aside className={`glass-sidebar fixed inset-y-0 left-0 hidden border-r py-6 lg:flex lg:flex-col transition-[width,padding] duration-300 ease-out ${sidebarCollapsed ? "w-20 px-2" : "w-64 px-5"}`}>
      <div className={`flex items-center px-2 ${sidebarCollapsed ? "justify-center gap-1" : "gap-3"}`}><Avatar className={`h-10 w-10 shrink-0 rounded-2xl shadow-lg shadow-primary/20 ${sidebarCollapsed ? "h-9 w-9" : ""}`}><AvatarImage src={user.avatarUrl ?? undefined} alt={user.name ?? "Avatar do usuário"} /><AvatarFallback>LO</AvatarFallback></Avatar>{!sidebarCollapsed && <div><p className="font-semibold tracking-tight">Findash LVO</p><p className="text-xs text-muted-foreground">Seu dinheiro, claro.</p></div>}<button type="button" onClick={() => setSidebarCollapsed(value => !value)} className={`${sidebarCollapsed ? "h-9 w-9 shrink-0 p-1" : "ml-auto p-1.5"} rounded-lg border border-white/10 text-muted-foreground transition hover:border-primary/40 hover:text-foreground`} aria-label={sidebarCollapsed ? "Expandir menu lateral" : "Recolher menu lateral"}>{sidebarCollapsed ? <PanelLeftOpen className="h-4 w-4" /> : <PanelLeftClose className="h-4 w-4" />}</button></div>
      <nav className="mt-12 space-y-2"><NavItem collapsed={sidebarCollapsed} icon={LayoutDashboard} label="Visão geral" active={!isTransactions && !isInvestments && !isCreditCards} onClick={() => setLocation("/")} /><NavItem collapsed={sidebarCollapsed} icon={ReceiptText} label="Lançamentos" active={isTransactions} onClick={() => setLocation("/lancamentos")} /><NavItem collapsed={sidebarCollapsed} icon={BriefcaseBusiness} label="Investimentos" active={isInvestments} onClick={() => setLocation("/investimentos")} /><NavItem collapsed={sidebarCollapsed} icon={CreditCardIcon} label="Cartões" active={isCreditCards} onClick={() => setLocation("/cartoes")} /></nav>
      <div className={`mt-auto rounded-2xl border border-white/8 bg-white/[0.03] p-3 ${sidebarCollapsed ? "px-2" : ""}`}><div className={`flex items-center ${sidebarCollapsed ? "justify-center" : "gap-3"}`}><Avatar className="h-9 w-9 shrink-0"><AvatarImage src={user.avatarUrl ?? undefined} alt={user.name ?? "Avatar do usuário"} /><AvatarFallback>LO</AvatarFallback></Avatar>{!sidebarCollapsed && <div className="min-w-0"><p className="truncate text-sm font-medium">{user.name ?? "Usuário"}</p><p className="truncate text-xs text-muted-foreground">{user.email}</p></div>}</div><Button variant="ghost" size="sm" className={`mt-3 min-h-10 w-full text-muted-foreground ${sidebarCollapsed ? "justify-center px-0" : "justify-start"}`} disabled={loading} onClick={() => setLogoutOpen(true)} title={sidebarCollapsed ? "Sair" : undefined} aria-label="Sair"><LogOut className={`${sidebarCollapsed ? "" : "mr-2"} h-4 w-4`} />{!sidebarCollapsed && "Sair"}</Button></div>
    </aside>
    <main className={`transition-[padding] duration-300 ease-out ${sidebarCollapsed ? "lg:pl-20" : "lg:pl-64"}`}><header className="glass-header sticky top-0 z-20 border-b px-4 py-4 backdrop-blur-xl sm:px-8"><div className="mx-auto flex max-w-7xl items-center justify-between"><div><p className="text-xs font-medium uppercase tracking-[0.2em] text-primary">{isTransactions ? "Controle" : isInvestments ? "Patrimônio" : isCreditCards ? "Pagamentos" : "Resumo financeiro"}</p><h1 className="mt-1 text-xl font-semibold tracking-tight sm:text-2xl">{isTransactions ? "Seus lançamentos" : isInvestments ? "Sua carteira de investimentos" : isCreditCards ? "Seus cartões de crédito" : `Olá, ${user.name?.split(" ")[0] ?? "bem-vindo"}.`}</h1></div><div className="flex items-center gap-2"><div className="hidden items-center gap-2 rounded-xl border border-white/8 bg-white/[0.03] px-3 py-2 sm:flex"><CalendarDays className="h-4 w-4 text-muted-foreground" /><select className="bg-transparent text-sm outline-none" value={month} onChange={e => setMonth(Number(e.target.value))}>{monthNames.map((m, i) => <option className="bg-[#10131b]" key={m} value={i + 1}>{m}</option>)}</select><select className="bg-transparent text-sm outline-none" value={year} onChange={e => setYear(Number(e.target.value))}>{yearOptions.map(option => <option className="bg-[#10131b]" key={option} value={option}>{option}</option>)}</select></div><div className="hidden items-center gap-1 md:flex"><Button variant="outline" size="sm" className="rounded-xl border-white/15 bg-white/[0.03]" onClick={() => importInputRef.current?.click()} title="Importar backup"><Download className="mr-1.5 h-4 w-4 rotate-180" />Importar</Button><ExportMenu onJson={downloadBackup} onExcel={exportExcel} onPdf={exportPdf} /></div><input ref={importInputRef} type="file" accept="application/json,.json" className="hidden" onChange={importBackup} /><Button variant="outline" size="icon" className="rounded-xl border-white/15 bg-white/[0.03]" onClick={toggleTheme} title={theme === "dark" ? "Ativar light mode" : "Ativar dark mode"}>{theme === "dark" ? <Sun className="h-4 w-4" /> : <Moon className="h-4 w-4" />}</Button><Button size="icon" className="rounded-xl" onClick={() => setForm(initialForm())}><Plus className="h-5 w-5" /></Button></div></div></header>
      <div className="mx-auto max-w-7xl space-y-6 p-4 sm:p-8"><div className="grid grid-cols-2 gap-2 sm:hidden"><Button className="w-full px-2 text-xs" variant={!isTransactions && !isInvestments && !isCreditCards ? "secondary" : "ghost"} onClick={() => setLocation("/")}><LayoutDashboard className="mr-1.5 h-4 w-4 shrink-0" />Resumo</Button><Button className="w-full px-2 text-xs" variant={isTransactions ? "secondary" : "ghost"} onClick={() => setLocation("/lancamentos")}><ReceiptText className="mr-1.5 h-4 w-4 shrink-0" />Lançamentos</Button><Button className="w-full px-2 text-xs" variant={isInvestments ? "secondary" : "ghost"} onClick={() => setLocation("/investimentos")}><BriefcaseBusiness className="mr-1.5 h-4 w-4 shrink-0" />Investimentos</Button><Button className="w-full px-2 text-xs" variant={isCreditCards ? "secondary" : "ghost"} onClick={() => setLocation("/cartoes")}><CreditCardIcon className="mr-1.5 h-4 w-4 shrink-0" />Cartões</Button></div><div className="flex items-center gap-2 rounded-2xl border border-white/8 bg-white/[0.03] p-3 sm:hidden"><CalendarDays className="h-4 w-4 text-muted-foreground" /><select className="flex-1 bg-transparent text-sm outline-none" value={month} onChange={e => setMonth(Number(e.target.value))}>{monthNames.map((m, i) => <option className="bg-[#10131b]" key={m} value={i + 1}>{m}</option>)}</select><span className="text-muted-foreground">/</span><select className="bg-transparent text-sm outline-none" value={year} onChange={e => setYear(Number(e.target.value))}>{yearOptions.map(option => <option className="bg-[#10131b]" key={option} value={option}>{option}</option>)}</select></div><div className="flex flex-wrap gap-2 md:hidden"><Button variant="outline" size="sm" className="border-white/15 bg-white/[0.03]" onClick={() => importInputRef.current?.click()}><Download className="mr-1.5 h-4 w-4 rotate-180" />Importar</Button><ExportMenu compact onJson={downloadBackup} onExcel={exportExcel} onPdf={exportPdf} /><Button variant="outline" size="icon" className="border-white/15 bg-white/[0.03]" onClick={toggleTheme} title={theme === "dark" ? "Ativar light mode" : "Ativar dark mode"}>{theme === "dark" ? <Sun className="h-4 w-4" /> : <Moon className="h-4 w-4" />}</Button></div>{isTransactions ? <TransactionsPage grouped={grouped} onEdit={(item: any) => setForm({ id: item.id, type: item.type, description: item.description, amount: String(item.creditTotal ?? item.amount), category: item.category, icon: item.icon, occurredAt: new Date(item.occurredAt).toISOString().slice(0, 10), paymentMethod: item.paymentMethod, creditCardId: item.creditCardId, installmentsTotal: item.installmentsTotal ?? 1 })} onDelete={(id: number) => setDeleteRequest({ kind: "transaction", id })} /> : isInvestments ? <InvestmentsPage investments={investments} onAdd={() => setInvestmentForm(initialInvestmentForm())} onRefreshQuotes={refreshQuotes} quotesLoading={quoteQuery.isFetching} onEdit={(item: LocalInvestment) => setInvestmentForm({ id: item.id, ticker: item.ticker, category: item.category, institution: item.institution, quantity: "", averagePrice: "", currentValue: item.currentValue, operationType: "buy", operationDate: new Date().toISOString().slice(0, 10), notes: item.notes })} onDelete={(id: number) => setDeleteRequest({ kind: "investment", id })} historyTicker={historyTicker} historyOptions={investments.filter(item => item.ticker.trim()).map(item => item.ticker.trim().toUpperCase())} onHistoryTickerChange={setHistoryTicker} historyData={historyQuery.data ?? []} historyLoading={historyQuery.isFetching} historyRange={historyRange} onHistoryRangeChange={setHistoryRange} historyError={historyQuery.error?.message} /> : isCreditCards ? <CreditCardsPage cards={creditCards} onSave={saveCreditCard} onDelete={(id: number) => setDeleteRequest({ kind: "creditCard", id })} onTogglePaid={toggleCreditCardPaid} /> : <Dashboard summary={summary} transactions={visibleTransactions} allTransactions={transactions} month={month} year={year} selectedDate={selectedDate} paymentFilter={paymentFilter} onPaymentFilterChange={setPaymentFilter} performanceRange={performanceRange} onPerformanceRange={setPerformanceRange} onSelectDate={setSelectedDate} onAdd={() => setForm(initialForm())} investments={investments} onAddInvestment={() => setInvestmentForm(initialInvestmentForm())} onRefreshQuotes={refreshQuotes} quotesLoading={quoteQuery.isFetching} creditCards={creditCards} onToggleCreditCardPaid={toggleCreditCardPaid} onAddCreditCard={() => setLocation("/cartoes")} marketWidgetQuotes={marketWidgetQuery.data ?? []} />}</div>
    </main>
    <AlertDialog open={Boolean(deleteRequest)} onOpenChange={open => { if (!open) setDeleteRequest(null); }}><AlertDialogContent className="glass-modal max-w-md border-white/15"><AlertDialogHeader><AlertDialogTitle>Confirmar exclusão?</AlertDialogTitle><AlertDialogDescription>Esta ação remove permanentemente o registro financeiro selecionado deste navegador.</AlertDialogDescription></AlertDialogHeader><AlertDialogFooter><AlertDialogCancel>Cancelar</AlertDialogCancel><AlertDialogAction className="bg-rose-500 text-white hover:bg-rose-600" onClick={event => { event.preventDefault(); confirmDelete(); }}>Excluir</AlertDialogAction></AlertDialogFooter></AlertDialogContent></AlertDialog>
    <AlertDialog open={logoutOpen} onOpenChange={setLogoutOpen}><AlertDialogContent className="glass-modal max-w-md border-white/15"><AlertDialogHeader><AlertDialogTitle>Encerrar sessão?</AlertDialogTitle><AlertDialogDescription>Você será desconectado deste dispositivo. Seus dados locais permanecerão disponíveis neste navegador.</AlertDialogDescription></AlertDialogHeader><AlertDialogFooter><AlertDialogCancel disabled={loading}>Cancelar</AlertDialogCancel><AlertDialogAction disabled={loading} onClick={event => { event.preventDefault(); void confirmLogout(); }}>{loading ? <><Loader2 className="mr-2 h-4 w-4 animate-spin" />Encerrando...</> : "Sair da conta"}</AlertDialogAction></AlertDialogFooter></AlertDialogContent></AlertDialog>
    {form && <TransactionModal form={form} setForm={setForm} creditCards={creditCards} onSubmit={submit} saving={saving} onClose={() => setForm(null)} />}
    {investmentForm && <InvestmentModal form={investmentForm} setForm={setInvestmentForm} onClose={() => setInvestmentForm(null)} onSubmit={(event: React.FormEvent) => { event.preventDefault(); const quantity = Number(investmentForm.quantity || 0); const averagePrice = Number(investmentForm.averagePrice || 0); if (!investmentForm.ticker.trim() || !Number.isFinite(quantity) || quantity <= 0 || !Number.isFinite(averagePrice) || averagePrice < 0 || !investmentForm.operationDate) { toast.error("Preencha ticker, quantidade, preço médio e data válidos"); return; } const operation = { id: Date.now(), type: investmentForm.operationType, quantity: String(quantity), price: String(averagePrice), date: investmentForm.operationDate }; if (investmentForm.id) { setInvestments(current => current.map(item => item.id === investmentForm.id ? appendInvestmentOperation({ ...item, ticker: investmentForm.ticker.trim().toUpperCase(), category: investmentForm.category, institution: investmentForm.institution, notes: investmentForm.notes }, operation) : item)); toast.success("Operação registrada e posição consolidada"); } else { setInvestments(current => { const created = createLocalInvestment(current, { userId: Number(user.id), ticker: investmentForm.ticker.trim().toUpperCase(), category: investmentForm.category, institution: investmentForm.institution, quantity: "0", averagePrice: "0", currentValue: "0", operations: [], realizedProfit: "0", notes: investmentForm.notes }); const item = created[created.length - 1]; return created.map(entry => entry.id === item.id ? appendInvestmentOperation(item, operation) : entry); }); toast.success("Operação registrada; buscando cotação automaticamente"); } setInvestmentForm(null); }} />}
  </div>;
}

function NavItem({ icon: Icon, label, active, onClick, collapsed }: { icon: any; label: string; active: boolean; onClick: () => void; collapsed?: boolean }) { return <UiTooltip><TooltipTrigger asChild><button onClick={onClick} aria-current={active ? "page" : undefined} className={`flex w-full items-center rounded-xl px-3 py-3 text-sm transition-[background-color,color,box-shadow,transform] duration-200 ${collapsed ? "justify-center" : "gap-3"} ${active ? "bg-primary/20 text-primary shadow-lg shadow-primary/10 ring-1 ring-primary/20" : "text-muted-foreground hover:bg-white/5 hover:text-foreground"}`}><Icon className={`h-4 w-4 shrink-0 transition-transform duration-200 ${active ? "scale-110" : ""}`} />{!collapsed && label}</button></TooltipTrigger>{collapsed && <TooltipContent side="right">{label}</TooltipContent>}</UiTooltip>; }
function ExportMenu({ onJson, onExcel, onPdf, compact = false }: { onJson: () => void; onExcel: () => void; onPdf: () => void; compact?: boolean }) { return <DropdownMenu><DropdownMenuTrigger asChild><Button variant="outline" size="sm" className={`rounded-xl border-white/15 bg-white/[0.03] ${compact ? "flex-1" : ""}`}><Download className="mr-1.5 h-4 w-4" />Exportar</Button></DropdownMenuTrigger><DropdownMenuContent align="end" className="glass-panel min-w-44 border-white/15"><DropdownMenuItem onClick={onJson}><FileText className="h-4 w-4" />JSON</DropdownMenuItem><DropdownMenuItem onClick={onExcel}><FileSpreadsheet className="h-4 w-4" />Excel</DropdownMenuItem><DropdownMenuItem onClick={onPdf}><FileText className="h-4 w-4" />PDF</DropdownMenuItem></DropdownMenuContent></DropdownMenu>; }
function Landing({ onLogin }: { onLogin: () => void }) { const [isLoggingIn, setIsLoggingIn] = useState(false); const handleLogin = () => { setIsLoggingIn(true); onLogin(); }; return <div className="grid min-h-screen place-items-center bg-[#0b0d12] p-6"><div className="w-full max-w-md text-center"><div className="mx-auto mb-6 flex min-h-20 w-full max-w-[320px] items-center justify-center rounded-3xl bg-[#171326] p-4 shadow-2xl shadow-primary/25"><img src="/manus-storage/findash-lvo-logo_2ad1a08e.png" alt="Findash LVO" className="h-auto w-full object-contain" /></div><p className="mb-3 text-sm font-medium uppercase tracking-[0.25em] text-primary">Findash LVO</p><h1 className="text-4xl font-semibold tracking-tight sm:text-5xl">Finanças sem ruído.</h1><p className="mx-auto mt-5 max-w-sm text-muted-foreground">Organize entradas, saídas e decisões em um painel simples, visual e feito para você.</p><Button onClick={handleLogin} disabled={isLoggingIn} size="lg" className="mt-8 h-12 w-full rounded-xl">{isLoggingIn ? <><Loader2 className="mr-2 h-5 w-5 animate-spin" />Conectando ao Google...</> : "Entrar com Google"}</Button><p className="mt-4 text-xs text-muted-foreground">A autenticação segura carrega seu perfil automaticamente.</p></div></div>; }
function InvestmentAllocationCard({ title, data }: { title: string; data: Array<{ name: string; value: number }> }) { return <section className="glass-panel investment-card min-h-[240px] rounded-3xl border p-5"><div><p className="text-sm font-medium">{title}</p><p className="mt-1 text-xs text-muted-foreground">Distribuição pelo valor de mercado</p></div>{data.length ? <div className="mt-3 h-48"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={data} dataKey="value" nameKey="name" cx="50%" cy="48%" innerRadius={42} outerRadius={70} paddingAngle={3}>{data.map((entry, index) => <Cell key={entry.name} fill={chartColors[index % chartColors.length]} />)}</Pie><Tooltip formatter={(value: number) => money.format(value)} contentStyle={{ background: "#17131f", border: "1px solid rgba(255,255,255,.12)", borderRadius: 12 }} /><Legend iconType="circle" wrapperStyle={{ fontSize: 10 }} /></PieChart></ResponsiveContainer></div> : <div className="grid h-48 place-items-center text-sm text-muted-foreground">Cadastre investimentos para visualizar.</div>}</section>; }
function InvestmentAnnualPerformanceCard({ investments, year, range, onRangeChange }: { investments: LocalInvestment[]; year: number; range: "week" | "month" | "year"; onRangeChange: (range: "week" | "month" | "year") => void }) {
  const data = Array.from({ length: 12 }, (_, month) => {
    const cutoff = `${year}-${String(month + 1).padStart(2, "0")}-31`;
    const realized = investments.reduce((sum, item) => {
      const operations = (item.operations ?? []).filter(operation => operation.date <= cutoff);
      return sum + consolidateInvestmentOperations(operations).realizedProfit;
    }, 0);
    return { month: monthNames[month], balance: Number(realized.toFixed(2)) };
  });
  return <section className="glass-panel investment-card min-h-[340px] rounded-3xl border p-5 sm:p-6"><div className="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between"><div><p className="text-sm font-medium">Performance dos investimentos</p><p className="mt-1 text-xs text-muted-foreground">Evolução acumulada em diferentes escalas</p></div><div className="flex rounded-xl border border-white/10 bg-white/[0.04] p-1">{([["week", "Semanal"], ["month", "Mensal"], ["year", "Anual"]] as const).map(([value, label]) => <button key={value} onClick={() => onRangeChange(value)} className={`rounded-lg px-2.5 py-1.5 text-xs transition ${range === value ? "bg-primary text-primary-foreground" : "text-muted-foreground hover:text-foreground"}`}>{label}</button>)}</div></div>{investments.length ? <div className="mt-6 h-72"><ResponsiveContainer width="100%" height="100%"><AreaChart data={data}><defs><linearGradient id="investmentPerformanceFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#c084fc" stopOpacity={0.38} /><stop offset="100%" stopColor="#c084fc" stopOpacity={0} /></linearGradient></defs><CartesianGrid stroke="rgba(255,255,255,.06)" vertical={false} /><XAxis dataKey="month" axisLine={false} tickLine={false} tick={{ fill: "#8a91a4", fontSize: 11 }} /><YAxis axisLine={false} tickLine={false} tick={{ fill: "#8a91a4", fontSize: 11 }} tickFormatter={value => `R$${Math.round(value / 1000)}k`} /><Tooltip contentStyle={{ background: "#17131f", border: "1px solid rgba(255,255,255,.12)", borderRadius: 14 }} formatter={(value: number) => [money.format(value), "Resultado"]} /><Area type="monotone" dataKey="balance" stroke="#d19aff" strokeWidth={3} fill="url(#investmentPerformanceFill)" /></AreaChart></ResponsiveContainer></div> : <div className="mt-6 grid h-72 place-items-center text-sm text-muted-foreground">Cadastre investimentos para visualizar.</div>}</section>;
}
function MarketWidgets({ quotes }: { quotes: Array<{ ticker: string; price?: number; changePercent?: number | null; ok: boolean; error?: string }> }) { return <section className="glass-panel rounded-3xl border p-5"><p className="text-sm font-medium">Mercados de referência</p><p className="mt-1 text-xs text-muted-foreground">Cotações atualizadas automaticamente</p><div className="mt-4 grid gap-3 sm:grid-cols-2">{[{ ticker: "USD-BRL", label: "USD/BRL", currency: "BRL" }, { ticker: "BTC", label: "BTC/BRL", currency: "BRL" }].map(widget => { const quote = quotes.find(item => item.ticker === widget.ticker); const value = quote?.price; const positive = Number(quote?.changePercent ?? 0) >= 0; return <div key={widget.ticker} className="rounded-2xl border border-white/10 bg-white/[0.03] p-3"><p className="text-xs text-muted-foreground">{widget.label}</p><p className="mt-1 text-lg font-semibold">{quote?.ok && value !== undefined ? money.format(value) : "—"}</p>{quote?.ok && quote.changePercent !== null && quote.changePercent !== undefined && <p className={`mt-1 flex items-center gap-1 text-xs font-medium ${positive ? "text-emerald-400" : "text-rose-400"}`}>{positive ? <ArrowUpRight className="h-3 w-3" /> : <ArrowDownRight className="h-3 w-3" />}{positive ? "+" : ""}{Number(quote.changePercent).toFixed(2)}%</p>}{quote && !quote.ok && <p className="mt-1 text-xs text-rose-400">Indisponível</p>}</div>; })}</div></section>; }
function Dashboard({ summary, transactions, month, year, selectedDate, paymentFilter, onPaymentFilterChange, performanceRange, onPerformanceRange, onSelectDate, onAdd, investments, onAddInvestment, onRefreshQuotes, quotesLoading, creditCards, onToggleCreditCardPaid, onAddCreditCard, marketWidgetQuotes }: any) {
  const biggestExpenses = [...transactions].filter(item => item.type === "expense").sort((a, b) => Number(b.amount) - Number(a.amount)).slice(0, 3);
  const biggestIncome = [...transactions].filter(item => item.type === "income").sort((a, b) => Number(b.amount) - Number(a.amount)).slice(0, 3);
  const selectedTransactions = transactions.filter((item: LocalTransaction) => new Date(item.occurredAt).toISOString().slice(0, 10) === selectedDate);
  const performance = buildPerformanceData(transactions, year, month, performanceRange, selectedDate);
  const allocationByType = Object.entries(investments.reduce((acc: Record<string, number>, item: LocalInvestment) => {
    const label = investmentCategories.find(option => option.value === item.category)?.label ?? item.category;
    acc[label] = (acc[label] ?? 0) + investmentMarketValue(item);
    return acc;
  }, {})).map(([name, value]) => ({ name, value: Number(value) }));
  const allocationByInstitution = Object.entries(investments.reduce((acc: Record<string, number>, item: LocalInvestment) => {
    const label = item.institution || "Sem instituição";
    acc[label] = (acc[label] ?? 0) + investmentMarketValue(item);
    return acc;
  }, {})).map(([name, value]) => ({ name, value: Number(value) }));
  const widgetMap: Record<DashboardWidgetKey, React.ReactNode> = {
    market: <MarketWidgets quotes={marketWidgetQuotes} />,
    currency: <section className="glass-panel rounded-3xl border p-5"><p className="text-sm font-medium">Carteira em moedas</p><p className="mt-1 text-xs text-muted-foreground">Ativos da categoria dólar são exibidos em USD nos seus cards individuais.</p><div className="mt-4 grid grid-cols-2 gap-3"><div className="rounded-2xl bg-primary/10 p-3"><p className="text-xs text-muted-foreground">Posições</p><p className="mt-1 text-xl font-semibold">{investments.length}</p></div><div className="rounded-2xl bg-violet-400/10 p-3"><p className="text-xs text-muted-foreground">Categorias</p><p className="mt-1 text-xl font-semibold">{new Set(investments.map((item: LocalInvestment) => item.category)).size}</p></div></div></section>,
    expenses: <RankingCard title="Maiores gastos" items={biggestExpenses} empty="Nenhuma saída registrada" tone="expense" />,
    income: <RankingCard title="Maiores entradas" items={biggestIncome} empty="Nenhuma entrada registrada" tone="income" />,
    nextInvoice: <NextInvoiceCard cards={creditCards} onTogglePaid={onToggleCreditCardPaid} onAdd={onAddCreditCard} />,
    allocationType: <InvestmentAllocationCard title="Investimentos por tipo" data={allocationByType} />,
    allocationInstitution: <InvestmentAllocationCard title="Investimentos por instituição" data={allocationByInstitution} />,
    periodSummary: <section className="glass-panel rounded-3xl border p-5"><p className="text-sm font-medium">Resumo do período</p><p className="mt-1 text-xs text-muted-foreground">Use os filtros no cabeçalho para navegar entre meses e anos.</p><div className="mt-5 grid grid-cols-2 gap-3"><div className="rounded-2xl bg-emerald-400/8 p-4"><p className="text-xs text-muted-foreground">Entradas</p><p className="mt-2 text-lg font-semibold text-emerald-300">{money.format(summary.income)}</p></div><div className="rounded-2xl bg-rose-400/8 p-4"><p className="text-xs text-muted-foreground">Saídas</p><p className="mt-2 text-lg font-semibold text-rose-300">{money.format(summary.expense)}</p></div></div></section>,
  };
  const show = (key: DashboardWidgetKey) => widgetMap[key];
  const frame = (key: DashboardWidgetKey) => <div className="min-w-0">{widgetMap[key]}</div>;
  return <div className="space-y-6">
    <div className="flex flex-col gap-3 sm:flex-row sm:items-end sm:justify-between"><div><p className="text-xs font-medium uppercase tracking-[0.24em] text-primary">Painel financeiro</p><h2 className="mt-1 text-2xl font-semibold tracking-tight sm:text-3xl">Uma visão clara do seu dinheiro</h2></div><div className="flex flex-wrap items-center justify-between gap-2 sm:justify-end"><p className="text-sm text-muted-foreground">{monthNames[month - 1]} de {year}</p><label className="flex items-center gap-2 rounded-xl border border-white/15 bg-white/[0.03] px-3 py-2 text-xs text-muted-foreground"><span>Método</span><select aria-label="Filtrar lançamentos por método de pagamento" className="bg-transparent text-foreground outline-none" value={paymentFilter} onChange={event => onPaymentFilterChange(event.target.value)}><option className="bg-[#10131b]" value="all">Todos</option><option className="bg-[#10131b]" value="cash">Dinheiro</option><option className="bg-[#10131b]" value="pix">Pix</option><option className="bg-[#10131b]" value="boleto">Boleto</option><option className="bg-[#10131b]" value="debit">Débito</option><option className="bg-[#10131b]" value="credit">Crédito</option></select></label></div></div>
    <div className="grid items-start gap-4 xl:grid-cols-3"><div className="min-w-0"><Metric title="Saldo no período" value={money.format(summary.income - summary.expense)} icon={Wallet} accent="text-primary" helper="Resultado líquido" /><div className="mt-4 min-h-[360px]"><CalendarCard compact allTransactions={transactions} month={month} year={year} selectedDate={selectedDate} onSelectDate={onSelectDate} /></div></div><div className="min-w-0 space-y-4">{show("expenses")}{show("income")}{show("nextInvoice")}</div><div className="min-w-0"><InvestmentCard investments={investments} onAdd={onAddInvestment} onRefreshQuotes={onRefreshQuotes} quotesLoading={quotesLoading} /></div><div className="min-w-0 xl:col-span-2"><div className="grid items-stretch gap-4 md:grid-cols-2">{frame("allocationType")}{frame("allocationInstitution")}</div></div><div className="min-w-0 space-y-4">{frame("market")}{frame("currency")}</div></div>
    <div className="grid items-stretch gap-4 md:grid-cols-2"><div className="min-w-0"><SelectedDayCard date={selectedDate} transactions={selectedTransactions} onAdd={onAdd} /></div>{frame("periodSummary")}</div>
    <div className="min-w-0"><PerformanceCard data={performance} range={performanceRange} onRangeChange={onPerformanceRange} /></div>
    <div className="min-w-0"><InvestmentAnnualPerformanceCard investments={investments} year={year} range={performanceRange} onRangeChange={onPerformanceRange} /></div>
  </div>;
}

function RankingCard({ title, items, empty, tone }: any) { return <section className="glass-panel dashboard-card min-h-[112px] rounded-3xl border p-5"><div className="flex items-start justify-between"><div><p className="text-sm font-medium">{title}</p><p className="mt-1 text-xs text-muted-foreground">No período selecionado</p></div>{tone === "income" ? <ArrowUpRight className="h-5 w-5 text-emerald-400" /> : <ArrowDownRight className="h-5 w-5 text-rose-400" />}</div><div className="mt-5 space-y-3">{items.length ? items.map((item: LocalTransaction, index: number) => <div className="flex items-center gap-3" key={item.id}><span className={`grid h-7 w-7 place-items-center rounded-lg text-xs font-semibold ${tone === "income" ? "bg-emerald-400/10 text-emerald-300" : "bg-rose-400/10 text-rose-300"}`}>{index + 1}</span><div className="min-w-0 flex-1"><p className="truncate text-sm">{item.description}</p><p className="truncate text-xs text-muted-foreground">{item.category}</p></div><strong className={`text-sm ${tone === "income" ? "text-emerald-300" : "text-rose-300"}`}>{money.format(Number(item.amount))}</strong></div>) : <p className="py-4 text-sm text-muted-foreground">{empty}</p>}</div></section>; }

function InvestmentCard({ investments, onAdd, onRefreshQuotes, quotesLoading }: any) { const total = investments.reduce((sum: number, item: LocalInvestment) => sum + investmentMarketValue(item), 0); const cost = investments.reduce((sum: number, item: LocalInvestment) => sum + investmentCost(item), 0); const latestQuote = [...investments].filter(item => item.quoteFetchedAt).sort((a, b) => String(b.quoteFetchedAt).localeCompare(String(a.quoteFetchedAt)))[0]; return <section className="glass-panel dashboard-card investment-card min-h-[280px] relative overflow-hidden rounded-3xl border p-5"><div className="absolute -right-10 -top-10 h-32 w-32 rounded-full bg-primary/15 blur-3xl" /><div className="flex items-start justify-between"><div><p className="text-sm font-medium">Carteira de investimentos</p><p className="mt-1 text-xs text-muted-foreground">Valor de mercado acompanhado</p></div><BriefcaseBusiness className="h-5 w-5 text-primary" /></div><div className="mt-6"><p className="text-2xl font-semibold">{investments.length ? money.format(total) : "—"}</p><p className="mt-1 text-xs text-muted-foreground">Custo total: {investments.length ? money.format(cost) : "—"}</p><p className="mt-1 text-xs text-muted-foreground">{investments.length ? `${investments.length} posição(ões)` : "Nenhuma posição cadastrada"}</p><p className="mt-2 text-[11px] text-muted-foreground">{latestQuote?.quoteFetchedAt ? latestQuote.quoteError ? `Cotação indisponível: ${latestQuote.quoteError}` : <>{`Última cotação: ${new Date(latestQuote.quoteFetchedAt).toLocaleString("pt-BR")} · ${latestQuote.quoteSource ?? "brapi.dev"}`}{latestQuote.quoteChangePercent !== undefined && <UiTooltip><TooltipTrigger asChild><span tabIndex={0} aria-label="Ver fechamento anterior" className={`ml-1 inline-flex cursor-help items-center gap-0.5 font-medium outline-none focus-visible:rounded focus-visible:ring-2 focus-visible:ring-primary ${Number(latestQuote.quoteChangePercent) >= 0 ? "text-emerald-400" : "text-rose-400"}`}>{Number(latestQuote.quoteChangePercent) >= 0 ? <ArrowUpRight className="h-3 w-3" /> : <ArrowDownRight className="h-3 w-3" />}{Number(latestQuote.quoteChangePercent) >= 0 ? "+" : ""}{Number(latestQuote.quoteChangePercent).toFixed(2)}%</span></TooltipTrigger><TooltipContent>Fechamento anterior: {latestQuote.quotePreviousClose !== undefined ? money.format(Number(latestQuote.quotePreviousClose)) : "indisponível"}</TooltipContent></UiTooltip>}</> : "Última cotação: ainda não atualizada"}</p></div><div className="mt-5 grid grid-cols-2 gap-2"><Button variant="secondary" size="sm" className="rounded-xl" onClick={onAdd}><Plus className="mr-2 h-4 w-4" />Cadastrar</Button><Button variant="ghost" size="sm" className="rounded-xl" onClick={onRefreshQuotes} disabled={quotesLoading || !investments.some((item: LocalInvestment) => item.ticker)}>{quotesLoading ? <><Loader2 className="mr-2 h-4 w-4 animate-spin" />Atualizando…</> : "Atualizar"}</Button></div></section>; }

function AssetPerformanceChart({ ticker, options, onTickerChange, data, loading, range, onRangeChange, error }: { ticker: string; options: string[]; onTickerChange: (ticker: string) => void; data: Array<{ date: number; close: number }>; loading: boolean; range: "1mo" | "6mo" | "1y"; onRangeChange: (range: "1mo" | "6mo" | "1y") => void; error?: string }) { const chartData = data.map(point => ({ date: new Date(point.date * 1000).toLocaleDateString("pt-BR", { month: "short", day: "2-digit" }), value: point.close })); return <section className="glass-panel rounded-3xl border p-5 sm:p-6"><div className="flex items-start justify-between"><div><p className="text-sm font-medium">Desempenho histórico</p><p className="mt-1 text-xs text-muted-foreground">{ticker ? `${ticker} · fechamento diário · ${range === "1mo" ? "1 mês" : range === "6mo" ? "6 meses" : "1 ano"}` : "Cadastre um ativo com ticker"}</p></div><div className="flex flex-wrap items-center gap-2">{options.length > 1 && <select className="rounded-lg border border-white/10 bg-white/[0.04] px-2 py-1 text-xs outline-none" value={ticker} onChange={event => onTickerChange(event.target.value)}>{options.map(option => <option className="bg-[#10131b]" key={option} value={option}>{option}</option>)}</select>}<div className="flex rounded-lg border border-white/10 bg-white/[0.04] p-0.5">{([["1mo", "1 mês"], ["6mo", "6 meses"], ["1y", "1 ano"]] as const).map(([value, label]) => <button type="button" key={value} onClick={() => onRangeChange(value)} className={`rounded-md px-2 py-1 text-[11px] transition ${range === value ? "bg-primary text-primary-foreground" : "text-muted-foreground hover:text-foreground"}`}>{label}</button>)}</div></div></div>{loading ? <div className="grid h-56 place-items-center text-sm text-muted-foreground">Carregando histórico…</div> : error ? <div className="mt-5 rounded-2xl border border-dashed border-rose-400/20 p-6 text-center text-sm text-muted-foreground">Histórico indisponível: {error}</div> : chartData.length ? <div className="mt-5 h-56"><ResponsiveContainer width="100%" height="100%"><AreaChart data={chartData}><defs><linearGradient id="assetPerformance" x1="0" y1="0" x2="0" y2="1"><stop offset="5%" stopColor="#a855f7" stopOpacity={0.35} /><stop offset="95%" stopColor="#a855f7" stopOpacity={0} /></linearGradient></defs><CartesianGrid stroke="rgba(255,255,255,0.08)" vertical={false} /><XAxis dataKey="date" tick={{ fill: "#94a3b8", fontSize: 10 }} tickLine={false} axisLine={false} minTickGap={28} /><YAxis tick={{ fill: "#94a3b8", fontSize: 10 }} tickLine={false} axisLine={false} width={54} /><Tooltip contentStyle={{ background: "#151622", border: "1px solid rgba(255,255,255,0.12)", borderRadius: 12 }} formatter={(value: number) => [money.format(value), "Fechamento"]} /><Area type="monotone" dataKey="value" stroke="#c084fc" fill="url(#assetPerformance)" strokeWidth={2} /></AreaChart></ResponsiveContainer></div> : <div className="mt-5 rounded-2xl border border-dashed border-white/10 p-6 text-center text-sm text-muted-foreground">Nenhum histórico disponível para este ticker.</div>}</section>; }

function CalendarCard({ allTransactions, month, year, selectedDate, onSelectDate, compact = false }: any) { const daysInMonth = new Date(year, month, 0).getDate(); const firstDay = (new Date(year, month - 1, 1).getDay() + 6) % 7; const byDate = new Map<string, LocalTransaction[]>(); allTransactions.forEach((item: LocalTransaction) => { const key = new Date(item.occurredAt).toISOString().slice(0, 10); byDate.set(key, [...(byDate.get(key) ?? []), item]); }); return <section className={`glass-panel rounded-3xl border ${compact ? "p-4" : "p-5 sm:p-6"}`}><div className="flex items-start justify-between"><div><p className="text-sm font-medium">Calendário financeiro</p><p className="mt-1 text-xs text-muted-foreground">Clique em um dia</p></div><CalendarDays className="h-5 w-5 text-primary" /></div><div className={`${compact ? "mt-3 gap-0.5" : "mt-5 gap-1"} grid grid-cols-7 text-center text-[11px] text-muted-foreground`}>{["S", "T", "Q", "Q", "S", "S", "D"].map((label, index) => <span key={`${label}-${index}`} className="py-1">{label}</span>)}{Array.from({ length: firstDay }).map((_, index) => <span key={`blank-${index}`} />)}{Array.from({ length: daysInMonth }, (_, index) => index + 1).map(day => { const key = `${year}-${String(month).padStart(2, "0")}-${String(day).padStart(2, "0")}`; const entries = byDate.get(key) ?? []; const active = selectedDate === key; return <button key={key} onClick={() => onSelectDate(key)} className={`relative grid aspect-square place-items-center rounded-xl ${compact ? "text-xs" : "text-sm"} transition ${active ? "bg-primary text-primary-foreground shadow-lg shadow-primary/20" : "hover:bg-white/8"}`}>{day}{entries.length > 0 && <span className={`absolute bottom-1 h-1 w-1 rounded-full ${entries.some(item => item.type === "income") ? "bg-emerald-400" : "bg-rose-400"}`} />}</button>; })}</div><div className="mt-4 flex items-center gap-4 text-[11px] text-muted-foreground"><span className="flex items-center gap-1.5"><i className="h-1.5 w-1.5 rounded-full bg-emerald-400" />Entradas</span><span className="flex items-center gap-1.5"><i className="h-1.5 w-1.5 rounded-full bg-rose-400" />Saídas</span></div></section>; }

function SelectedDayCard({ date, transactions, onAdd }: any) { return <section className="glass-panel rounded-3xl border p-5 sm:p-6"><div className="flex items-start justify-between"><div><p className="text-sm font-medium">Lançamentos do dia</p><p className="mt-1 text-xs text-muted-foreground">{new Date(`${date}T12:00:00`).toLocaleDateString("pt-BR", { day: "2-digit", month: "long", year: "numeric" })}</p></div><Button variant="ghost" size="icon" onClick={onAdd}><Plus className="h-4 w-4" /></Button></div><div className="mt-5 space-y-2">{transactions.length ? transactions.map((item: LocalTransaction) => <TransactionRow key={item.id} item={item} />) : <div className="rounded-2xl border border-dashed border-white/10 p-6 text-center text-sm text-muted-foreground">Nenhum lançamento nesta data.</div>}</div></section>; }

function buildPerformanceData(transactions: LocalTransaction[], year: number, month: number, range: "week" | "month" | "year", selectedDate: string) { const points = range === "year" ? monthNames.map((label, index) => ({ label, start: new Date(year, index, 1), end: new Date(year, index + 1, 0, 23, 59, 59) })) : range === "month" ? Array.from({ length: new Date(year, month, 0).getDate() }, (_, index) => ({ label: String(index + 1), start: new Date(year, month - 1, index + 1), end: new Date(year, month - 1, index + 1, 23, 59, 59) })) : Array.from({ length: 7 }, (_, index) => { const end = new Date(`${selectedDate}T12:00:00`); end.setDate(end.getDate() - (6 - index)); return { label: end.toLocaleDateString("pt-BR", { weekday: "short" }).replace(".", ""), start: new Date(end.getFullYear(), end.getMonth(), end.getDate()), end: new Date(end.getFullYear(), end.getMonth(), end.getDate(), 23, 59, 59) }; }); let balance = 0; return points.map(point => { transactions.filter(item => { const date = new Date(item.occurredAt); return date >= point.start && date <= point.end; }).forEach(item => { balance += item.type === "income" ? Number(item.amount) : -Number(item.amount); }); return { month: point.label, balance }; }); }

function PerformanceCard({ data, range, onRangeChange }: any) { return <section className="glass-panel rounded-3xl border p-5 sm:p-6"><div className="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between"><div><p className="text-sm font-medium">Performance financeira</p><p className="mt-1 text-xs text-muted-foreground">Evolução acumulada em diferentes escalas</p></div><div className="flex rounded-xl border border-white/10 bg-white/[0.04] p-1">{([["week", "Semanal"], ["month", "Mensal"], ["year", "Anual"]] as const).map(([value, label]) => <button key={value} onClick={() => onRangeChange(value)} className={`rounded-lg px-2.5 py-1.5 text-xs transition ${range === value ? "bg-primary text-primary-foreground" : "text-muted-foreground hover:text-foreground"}`}>{label}</button>)}</div></div><div className="mt-6 h-72"><ResponsiveContainer width="100%" height="100%"><AreaChart data={data}><defs><linearGradient id="performanceFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#c084fc" stopOpacity={0.38} /><stop offset="100%" stopColor="#c084fc" stopOpacity={0} /></linearGradient></defs><CartesianGrid stroke="rgba(255,255,255,.06)" vertical={false} /><XAxis dataKey="month" axisLine={false} tickLine={false} tick={{ fill: "#8a91a4", fontSize: 11 }} /><YAxis axisLine={false} tickLine={false} tick={{ fill: "#8a91a4", fontSize: 11 }} tickFormatter={value => `R$${Math.round(value / 1000)}k`} /><Tooltip contentStyle={{ background: "#17131f", border: "1px solid rgba(255,255,255,.12)", borderRadius: 14 }} formatter={(value: number) => money.format(value)} /><Area type="monotone" dataKey="balance" stroke="#d19aff" strokeWidth={3} fill="url(#performanceFill)" /></AreaChart></ResponsiveContainer></div></section>; }
function Metric({ title, value, icon: Icon, accent }: any) { return <div className="glass-panel min-h-[104px] rounded-3xl border p-5"><div className="flex items-center justify-between"><p className="text-sm text-muted-foreground">{title}</p><Icon className={`h-5 w-5 ${accent}`} /></div><p className="mt-5 text-2xl font-semibold tracking-tight">{value}</p></div>; }
function TransactionsPage({ grouped, onEdit, onDelete }: any) { return <div className="space-y-6"><div className="flex flex-col justify-between gap-3 sm:flex-row sm:items-end"><div><h2 className="text-2xl font-semibold">Entradas e saídas</h2><p className="mt-1 text-sm text-muted-foreground">Gerencie cada movimento do seu mês.</p></div><p className="text-sm text-muted-foreground">{grouped.income.length + grouped.expense.length} registros</p></div><div className="grid gap-6 xl:grid-cols-2"><TransactionColumn title="Entradas" subtitle="Receitas, salários e ganhos" items={grouped.income} tone="income" onEdit={onEdit} onDelete={onDelete} /><TransactionColumn title="Saídas" subtitle="Despesas e compromissos" items={grouped.expense} tone="expense" onEdit={onEdit} onDelete={onDelete} /></div></div>; }
function TransactionColumn({ title, subtitle, items, tone, onEdit, onDelete }: any) { return <section className="glass-panel rounded-3xl border p-5 sm:p-6"><div className="flex items-center gap-3"><div className={`grid h-10 w-10 place-items-center rounded-2xl ${tone === "income" ? "bg-emerald-400/12 text-emerald-400" : "bg-rose-400/12 text-rose-400"}`}>{tone === "income" ? <CircleArrowUp className="h-5 w-5" /> : <CircleArrowDown className="h-5 w-5" />}</div><div><h3 className="font-semibold">{title}</h3><p className="text-xs text-muted-foreground">{subtitle}</p></div></div><div className="mt-5 space-y-2">{items.length ? items.map((item: any) => <TransactionRow key={item.id} item={item} actions onEdit={onEdit} onDelete={onDelete} />) : <p className="rounded-2xl border border-dashed border-white/10 py-10 text-center text-sm text-muted-foreground">Nenhum registro aqui.</p>}</div></section>; }
function TransactionRow({ item, actions, onEdit, onDelete }: any) { return <div className="group flex items-center gap-3 rounded-2xl px-3 py-3 transition-colors hover:bg-white/[0.04]"><div className={`grid h-9 w-9 shrink-0 place-items-center rounded-xl ${item.type === "income" ? "bg-emerald-400/10 text-emerald-400" : "bg-rose-400/10 text-rose-400"}`}><span className="text-sm">{item.icon || (item.type === "income" ? "↗" : "◒")}</span></div><div className="min-w-0 flex-1"><p className="truncate text-sm font-medium">{item.description}</p><p className="text-xs text-muted-foreground">{item.category} · {new Date(item.occurredAt).toLocaleDateString("pt-BR")}</p></div><p className={`text-sm font-semibold ${item.type === "income" ? "text-emerald-400" : "text-rose-400"}`}>{item.type === "income" ? "+" : "−"}{money.format(Number(item.amount))}</p>{actions && <div className="hidden gap-1 group-hover:flex"><Button variant="ghost" size="icon" className="h-8 w-8" onClick={() => onEdit(item)}><ChevronDown className="h-4 w-4 rotate-[-90deg]" /></Button><Button variant="ghost" size="icon" className="h-8 w-8 text-rose-400" onClick={() => onDelete(item.id)}><Trash2 className="h-4 w-4" /></Button></div>}</div>; }
function EmptyState({ text, onClick }: any) { return <div className="grid h-full place-items-center rounded-2xl border border-dashed border-white/10 p-6 text-center"><div><p className="text-sm text-muted-foreground">{text}</p><Button variant="secondary" className="mt-4" onClick={onClick}><Plus className="mr-2 h-4 w-4" />Adicionar lançamento</Button></div></div>; }
function TransactionModal({ form, setForm, creditCards, onSubmit, saving, onClose }: any) { return <div className="fixed inset-0 z-50 grid place-items-end bg-black/60 p-0 backdrop-blur-md sm:place-items-center sm:p-4"><div className="glass-modal w-full max-w-lg rounded-t-3xl border p-5 shadow-2xl sm:rounded-3xl sm:p-6"><div className="mb-5 flex items-start justify-between"><div><p className="text-xs font-medium uppercase tracking-[0.2em] text-primary">Novo movimento</p><h2 className="mt-1 text-xl font-semibold">{form.id ? "Editar lançamento" : "Adicionar lançamento"}</h2></div><Button variant="ghost" size="icon" onClick={onClose}><X className="h-5 w-5" /></Button></div><form onSubmit={onSubmit} className="space-y-4"><div className="grid grid-cols-2 gap-2">{(["income", "expense"] as const).map(type => <button type="button" key={type} onClick={() => setForm({ ...form, type, paymentMethod: type === "expense" ? (form.paymentMethod ?? "cash") : undefined })} className={`rounded-xl border px-3 py-3 text-sm font-medium ${form.type === type ? (type === "income" ? "border-emerald-400/40 bg-emerald-400/10 text-emerald-400" : "border-rose-400/40 bg-rose-400/10 text-rose-400") : "border-white/10 text-muted-foreground"}`}>{type === "income" ? "Entrada" : "Saída"}</button>)}</div>{form.type === "expense" && <div className="space-y-2"><Label>Forma de pagamento</Label><div className="grid grid-cols-2 gap-2 sm:grid-cols-5">{([["cash", "Dinheiro"], ["pix", "Pix"], ["boleto", "Boleto"], ["debit", "Débito"], ["credit", "Crédito"]] as const).map(([value, label]) => <button type="button" key={value} onClick={() => setForm({ ...form, paymentMethod: value, creditCardId: value === "credit" ? form.creditCardId : undefined, installmentsTotal: value === "credit" ? (form.installmentsTotal ?? 1) : undefined })} className={`rounded-xl border px-2 py-2 text-xs font-medium ${form.paymentMethod === value ? "border-primary/50 bg-primary/10 text-primary" : "border-white/10 text-muted-foreground"}`}>{label}</button>)}</div></div>}{form.type === "expense" && form.paymentMethod === "credit" && <div className="grid gap-3 rounded-2xl border border-primary/20 bg-primary/[0.04] p-4 sm:col-span-2 sm:grid-cols-2"><div className="space-y-2"><Label>Cartão cadastrado</Label><select className="h-10 w-full rounded-xl border border-white/10 bg-white/[0.04] px-3 text-sm" value={form.creditCardId ?? ""} onChange={event => setForm({ ...form, creditCardId: event.target.value ? Number(event.target.value) : undefined })}><option value="">Selecione um cartão</option>{creditCards.map((card: CreditCard) => <option key={card.id} value={card.id}>{card.name} · {card.bank}</option>)}</select></div><div className="space-y-2"><Label>Quantidade de parcelas</Label><Input type="number" min="1" step="1" value={form.installmentsTotal ?? 1} onChange={event => setForm({ ...form, installmentsTotal: Math.max(1, Number(event.target.value) || 1) })} /></div>{creditCards.find((card: CreditCard) => card.id === form.creditCardId)?.cardType === "shared" && <div className="space-y-2 sm:col-span-2"><Label>Comprador</Label><Input value={form.buyer ?? ""} onChange={event => setForm({ ...form, buyer: event.target.value })} placeholder="Quem realizou a compra?" /></div>}<p className="text-xs text-muted-foreground sm:col-span-2">A fatura será atualizada com o valor total dividido igualmente entre as parcelas.</p></div>}<div className="grid gap-4 sm:grid-cols-2"><div className="space-y-2 sm:col-span-2"><Label>Descrição</Label><Input value={form.description} onChange={e => setForm({ ...form, description: e.target.value })} placeholder="Ex.: Salário, aluguel..." /></div><div className="space-y-2"><Label>{form.paymentMethod === "credit" ? "Valor total da compra" : "Valor"}</Label><Input type="number" min="0" step="0.01" value={form.amount} onChange={e => setForm({ ...form, amount: e.target.value })} placeholder="0,00" /></div><div className="space-y-2 sm:col-span-2"><Label>Categoria e ícone</Label><div className="grid grid-cols-2 gap-2 sm:grid-cols-4">{[{ label: "Moradia", icon: "⌂" }, { label: "Alimentação", icon: "◒" }, { label: "Transporte", icon: "↗" }, { label: "Lazer", icon: "✦" }, { label: "Salário", icon: "↙" }, { label: "Investimentos", icon: "◈" }].map(option => <button type="button" key={option.label} onClick={() => setForm({ ...form, category: option.label, icon: option.icon })} className={`rounded-xl border p-2.5 text-left transition ${form.category === option.label ? "border-primary/50 bg-primary/10" : "border-white/10 bg-white/[0.02] hover:bg-white/[0.05]"}`}><span className="mr-2 text-primary">{option.icon}</span><span className="text-xs">{option.label}</span></button>)}</div><Input value={form.category} onChange={e => setForm({ ...form, category: e.target.value, icon: "✦" })} placeholder="Ou digite uma categoria personalizada" /></div><div className="space-y-2 sm:col-span-2"><Label>Data</Label><Input type="date" value={form.occurredAt} onChange={e => setForm({ ...form, occurredAt: e.target.value })} /></div></div><Button type="submit" disabled={saving} className="h-11 w-full rounded-xl">{saving ? "Salvando..." : form.id ? "Salvar alterações" : "Adicionar lançamento"}</Button></form></div></div>; }

function InvestmentsPage({ investments, onAdd, onRefreshQuotes, quotesLoading, onEdit, onDelete, historyTicker, historyOptions, onHistoryTickerChange, historyData, historyLoading, historyRange, onHistoryRangeChange, historyError }: { investments: LocalInvestment[]; onAdd: () => void; onRefreshQuotes: () => void; quotesLoading: boolean; onEdit: (item: LocalInvestment) => void; onDelete: (id: number) => void; historyTicker: string; historyOptions: string[]; onHistoryTickerChange: (ticker: string) => void; historyData: Array<{ date: number; close: number }>; historyLoading: boolean; historyRange: "1mo" | "6mo" | "1y"; onHistoryRangeChange: (range: "1mo" | "6mo" | "1y") => void; historyError?: string }) { const total = investments.reduce((sum, item) => sum + investmentMarketValue(item), 0); const cost = investments.reduce((sum, item) => sum + investmentCost(item), 0); return <div className="space-y-6"><div className="flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between"><div><p className="text-xs font-medium uppercase tracking-[0.24em] text-primary">Patrimônio pessoal</p><h2 className="mt-1 text-2xl font-semibold tracking-tight sm:text-3xl">Sua carteira de investimentos</h2><p className="mt-2 text-sm text-muted-foreground">Cadastre e acompanhe suas posições no armazenamento local.</p>{(() => { const latest = [...investments].filter(item => item.quoteFetchedAt).sort((a, b) => String(b.quoteFetchedAt).localeCompare(String(a.quoteFetchedAt)))[0]; return <p className="mt-2 text-xs text-muted-foreground">{latest?.quoteFetchedAt ? latest.quoteError ? `Cotação indisponível: ${latest.quoteError}` : `Última atualização: ${new Date(latest.quoteFetchedAt).toLocaleString("pt-BR")} · ${latest.quoteSource ?? "brapi.dev"}` : "Última atualização: ainda não realizada"}</p>; })()}</div><div className="flex gap-2"><Button variant="secondary" onClick={onRefreshQuotes} disabled={quotesLoading || !investments.some(item => item.ticker)} className="rounded-xl">{quotesLoading ? <><Loader2 className="mr-2 h-4 w-4 animate-spin" />Atualizando…</> : <><Download className="mr-2 h-4 w-4" />Atualizar cotações</>}</Button><Button onClick={onAdd} className="rounded-xl"><Plus className="mr-2 h-4 w-4" />Nova posição</Button></div></div><div className="grid gap-4 sm:grid-cols-3"><Metric title="Valor de mercado" value={investments.length ? money.format(total) : "—"} icon={BriefcaseBusiness} accent="text-primary" /><Metric title="Custo total (q × PM)" value={investments.length ? money.format(cost) : "—"} icon={Wallet} accent="text-violet-300" /><Metric title="Posições" value={String(investments.length)} icon={Landmark} accent="text-emerald-400" /><Metric title="Categorias usadas" value={String(new Set(investments.map((item: LocalInvestment) => item.category)).size)} icon={Coins} accent="text-amber-300" /></div><AssetPerformanceChart ticker={historyTicker} options={historyOptions} onTickerChange={onHistoryTickerChange} data={historyData} loading={historyLoading} range={historyRange} onRangeChange={onHistoryRangeChange} error={historyError} /><section className="glass-panel rounded-3xl border p-5 sm:p-6"><div className="mb-5 flex items-center justify-between"><div><h3 className="font-semibold">Ativos cadastrados</h3><p className="mt-1 text-xs text-muted-foreground">Renda fixa, variável, fundos, dólar e cripto.</p></div><Button variant="secondary" size="sm" onClick={onAdd}><Plus className="mr-2 h-4 w-4" />Adicionar</Button></div>{investments.length ? <div className="grid gap-3 md:grid-cols-2 xl:grid-cols-3">{investments.map(item => { const category = investmentCategories.find(option => option.value === item.category); const profitability = investmentProfitability(item); return <article key={item.id} className="rounded-2xl border border-white/10 bg-white/[0.025] p-4"><div className="flex items-start justify-between gap-3"><div className="flex min-w-0 items-center gap-3"><img src={item.ticker ? `https://assets.parqet.com/logos/stocks/${encodeURIComponent(item.ticker.toUpperCase())}.png` : undefined} alt="" aria-hidden="true" className="h-9 w-9 rounded-xl border border-white/10 bg-white/[0.04] object-contain p-1" onError={event => { event.currentTarget.style.display = "none"; }} /><div className="min-w-0"><p className="font-medium">{item.ticker || item.name || "Ativo"}</p><p className="text-xs text-muted-foreground">{item.ticker || "Sem ticker"} · {category?.label}</p></div></div><div className="flex gap-1"><Button variant="ghost" size="icon" className="h-8 w-8" onClick={() => onEdit(item)}><Pencil className="h-3.5 w-3.5" /></Button><Button variant="ghost" size="icon" className="h-8 w-8 text-rose-400" onClick={() => onDelete(item.id)}><Trash2 className="h-3.5 w-3.5" /></Button></div></div><p className="mt-5 text-xl font-semibold">{formatInvestmentMoney(item, investmentMarketValue(item))}</p><p className="mt-1 text-xs text-muted-foreground">Quantidade: {Number(item.quantity).toLocaleString("pt-BR")} · PM: {formatInvestmentMoney(item, Number(item.averagePrice))}</p><p className="mt-1 text-xs text-muted-foreground">Custo consolidado: {formatInvestmentMoney(item, investmentCost(item))}</p><p className="mt-1 text-xs text-muted-foreground">{item.quoteError ? `Cotação indisponível: ${item.quoteError}` : item.quoteFetchedAt ? `Cotação ${item.quoteSource ?? "externa"} · ${new Date(item.quoteFetchedAt).toLocaleString("pt-BR")}` : "Sem cotação automática"}</p>{item.quoteChangePercent !== undefined && <UiTooltip><TooltipTrigger asChild><p tabIndex={0} aria-label="Ver fechamento anterior" className={`mt-1 inline-flex cursor-help items-center gap-1 text-xs font-medium outline-none focus-visible:rounded focus-visible:ring-2 focus-visible:ring-primary ${Number(item.quoteChangePercent) >= 0 ? "text-emerald-400" : "text-rose-400"}`}>{Number(item.quoteChangePercent) >= 0 ? <ArrowUpRight className="h-3.5 w-3.5" /> : <ArrowDownRight className="h-3.5 w-3.5" />}{Number(item.quoteChangePercent) >= 0 ? "+" : ""}{Number(item.quoteChangePercent).toFixed(2)}% no dia</p></TooltipTrigger><TooltipContent>Fechamento anterior: {item.quotePreviousClose !== undefined ? money.format(Number(item.quotePreviousClose)) : "indisponível"}</TooltipContent></UiTooltip>}<p className={`mt-1 text-xs font-medium ${profitability.percent >= 0 ? "text-emerald-400" : "text-rose-400"}`}>Rentabilidade: {profitability.percent >= 0 ? "+" : ""}{profitability.percent.toFixed(2)}%</p><p className="mt-1 text-xs text-muted-foreground">{item.institution || "Instituição não informada"}</p></article>; })}</div> : <div className="rounded-2xl border border-dashed border-white/10 p-10 text-center"><BriefcaseBusiness className="mx-auto h-8 w-8 text-primary" /><p className="mt-3 text-sm text-muted-foreground">Sua carteira ainda está vazia.</p><Button variant="secondary" className="mt-4" onClick={onAdd}><Plus className="mr-2 h-4 w-4" />Cadastrar primeiro ativo</Button></div>}</section></div>; }

function InvestmentModal({ form, setForm, onSubmit, onClose }: any) { return <div className="fixed inset-0 z-50 grid place-items-end bg-black/60 p-0 backdrop-blur-md sm:place-items-center sm:p-4"><div className="glass-modal max-h-[92vh] w-full max-w-2xl overflow-y-auto rounded-t-3xl border p-5 shadow-2xl sm:rounded-3xl sm:p-6"><div className="mb-5 flex items-start justify-between"><div><p className="text-xs font-medium uppercase tracking-[0.2em] text-primary">Carteira</p><h2 className="mt-1 text-xl font-semibold">{form.id ? "Editar posição" : "Cadastrar investimento"}</h2></div><Button variant="ghost" size="icon" onClick={onClose}><X className="h-5 w-5" /></Button></div><form onSubmit={onSubmit} className="space-y-4"><div className="grid gap-4 sm:grid-cols-2"><div className="space-y-2 sm:col-span-2"><Label>Operação</Label><div className="grid grid-cols-2 gap-2">{([['buy', 'Compra'], ['sell', 'Venda']] as const).map(([value, label]) => <button type="button" key={value} onClick={() => setForm({ ...form, operationType: value })} className={`rounded-xl border px-3 py-3 text-sm font-medium ${form.operationType === value ? (value === 'buy' ? 'border-emerald-400/40 bg-emerald-400/10 text-emerald-400' : 'border-rose-400/40 bg-rose-400/10 text-rose-400') : 'border-white/10 text-muted-foreground'}`}>{label}</button>)}</div></div><div className="space-y-2"><Label>Ticker ou código</Label><Input value={form.ticker} onChange={e => setForm({ ...form, ticker: e.target.value.toUpperCase() })} placeholder="Ex.: BOVA11, CDB" /></div><div className="space-y-2"><Label>Instituição</Label><Input value={form.institution} onChange={e => setForm({ ...form, institution: e.target.value })} placeholder="Ex.: Banco ou corretora" /></div><div className="space-y-2 sm:col-span-2"><Label>Categoria</Label><div className="grid gap-2 sm:grid-cols-2">{investmentCategories.map(option => <button type="button" key={option.value} onClick={() => setForm({ ...form, category: option.value })} className={`rounded-xl border p-3 text-left transition ${form.category === option.value ? "border-primary/50 bg-primary/10" : "border-white/10 bg-white/[0.02] hover:bg-white/[0.05]"}`}><p className="text-sm font-medium">{option.label}</p><p className="mt-1 text-xs text-muted-foreground">{option.detail}</p></button>)}</div></div><div className="space-y-2"><Label>Quantidade</Label><Input type="number" min="0" step="any" value={form.quantity} onChange={e => setForm({ ...form, quantity: e.target.value })} placeholder="0" /></div><div className="space-y-2"><Label>Preço da operação</Label><Input type="number" min="0" step="0.01" value={form.averagePrice} onChange={e => setForm({ ...form, averagePrice: e.target.value })} placeholder="0,00" /></div><div className="space-y-2"><Label>Data da operação</Label><Input type="date" value={form.operationDate} onChange={e => setForm({ ...form, operationDate: e.target.value })} /></div><div className="rounded-xl border border-dashed border-white/10 bg-white/[0.02] p-3 text-xs text-muted-foreground"><p className="font-medium text-foreground">Valor atual automático</p><p className="mt-1">O ticker identifica o ativo. O preço médio, a quantidade e a rentabilidade serão consolidados automaticamente a partir das operações.</p></div><div className="space-y-2"><Label>Observações</Label><Input value={form.notes} onChange={e => setForm({ ...form, notes: e.target.value })} placeholder="Opcional" /></div></div><Button type="submit" className="h-11 w-full rounded-xl">{form.id ? "Salvar posição" : "Cadastrar posição"}</Button></form></div></div>; }
